package util

import (
	"context"
	"testing"
	"time"
)

func TestStreamWritePCMBase64ToWav(t *testing.T) {
	data := make([]string, 5)
	data[0] = ``
	data[1] = ``
	data[2] = ``
	data[3] = ``
	data[4] = ``
	for index, dat := range data {
		err := StreamWritePCMBase64ToWav("test.wav", dat, false)
		if err != nil {
			t.Errorf("StreamWritePCMBase64ToWav failed: %v", err)
		} else {
			t.Logf("StreamWritePCMBase64ToWav succeeded for index %d", index)
		}
	}
	err := StreamWritePCMBase64ToWav("test.wav", "", true)
	if err != nil {
		t.Errorf("StreamWritePCMBase64ToWav failed with empty data: %v", err)
	} else {
		t.Logf("StreamWritePCMBase64ToWav succeeded with empty data")
	}
}

func TestChatSTT(t *testing.T) {
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	tr, err := ChatSTT(ctx, "https://interview.0x535a.cn/api/download/audio/453a4dcd-2000-4aff-8125-c8fe9209a31b.mp3")
	if err != nil {
		t.Errorf("ChatSTT failed: %v", err)
	} else {
		t.Logf("ChatSTT succeeded: %s", tr)
	}
}
